package com.blockbuster.core.common.model

/**
 * A persisted rule that blocks a domain or a keyword.
 *
 * @property id Identifier generated by the local database. Always greater than
 * zero for persisted rules.
 * @property pattern Domain or keyword to match.
 * @property type Category that determines how [pattern] is interpreted.
 * @property isEnabled Whether the rule participates in blocking.
 * @property createdAt Creation time in milliseconds since the epoch.
 */
data class BlockRule(
    val id: Long,
    val pattern: String,
    val type: BlockRuleType,
    val isEnabled: Boolean,
    val createdAt: Long,
)
